// src/lib/drive-mirror.ts (Node 24, no deps)
import { mkdir, readFile, writeFile, stat } from 'node:fs/promises';
import path from 'node:path';

const ROOT = process.env.IMAGE_MIRROR_DIR ?? './.image-mirror';
const MAX_W = 1600; // lh3 never upscales; =w1600 returns the original if smaller

export type MirrorKey = { id: string; version: string }; // version = Drive files.version or md5Checksum

export async function mirrorDrivePhoto({ id, version }: MirrorKey): Promise<string> {
  const file = path.join(ROOT, `${id}-${version}.jpg`);
  const meta = path.join(ROOT, `${id}-${version}.json`);
  if (await exists(file)) return file; // last-good: never refetch a stored version
  await mkdir(ROOT, { recursive: true });
  const url = `https://lh3.googleusercontent.com/d/${encodeURIComponent(id)}=w${MAX_W}`;
  const prev = (await exists(meta)) ? JSON.parse(await readFile(meta, 'utf8')) : {};
  for (let attempt = 0, delay = 500; attempt < 4; attempt++, delay *= 2) {
    const res = await fetch(url, { headers: prev.etag ? { 'If-None-Match': prev.etag } : {}, redirect: 'follow' });
    if (res.status === 304 && (await exists(file))) return file;
    if (res.ok && res.headers.get('content-type')?.startsWith('image/')) {
      await writeFile(file, Buffer.from(await res.arrayBuffer()));
      await writeFile(meta, JSON.stringify({ etag: res.headers.get('etag'), fetchedAt: Date.now() }));
      return file;
    }
    if (res.status === 429 || res.status >= 500) { await new Promise(r => setTimeout(r, delay)); continue; }
    throw new Error(`lh3 ${res.status} for ${id}`); // 403/500 also seen for unknown or unshared ids
  }
  throw new Error(`lh3 unavailable for ${id}`);
}

async function exists(p: string) { try { await stat(p); return true; } catch { return false; } }

import { GoogleAuth } from 'google-auth-library';
const auth = new GoogleAuth({ scopes: ['https://www.googleapis.com/auth/drive.readonly'] });

export async function driveMeta(id: string) {
  const client = await auth.getClient();
  const r = await client.request<{ version: string; md5Checksum?: string; mimeType: string; imageMediaMetadata?: { width: number; height: number } }>({
    url: `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(id)}?fields=version,md5Checksum,mimeType,imageMediaMetadata(width,height)`,
  });
  return r.data;
}

export async function driveBytes(id: string) {
  const client = await auth.getClient();
  const r = await client.request<ArrayBuffer>({
    url: `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(id)}?alt=media`,
    responseType: 'arraybuffer',
    retryConfig: { retry: 3, statusCodesToRetry: [[429, 429], [500, 599]] },
  });
  return Buffer.from(r.data);
}

